import request from '@/api/index'

// 分页查询监管机构
export function pageRegulatorOrg(query) {
  return request({
    url: '/prefund/regulatorOrg/page',
    method: 'post',
    data: query
  })
}

// 监管机构下拉列表
export function listRegulatorOrg(query) {
  return request({
    url: '/prefund/regulatorOrg/list',
    method: 'post',
    data: query
  })
}

// 监管机构详情
export function getRegulatorOrg(orgId) {
  return request({
    url: '/prefund/regulatorOrg/detail',
    method: 'post',
    data: { orgId: orgId }
  })
}

// 新增监管机构
export function addRegulatorOrg(data) {
  return request({
    url: '/prefund/regulatorOrg/add',
    method: 'post',
    data: data
  })
}

// 修改监管机构
export function updateRegulatorOrg(data) {
  return request({
    url: '/prefund/regulatorOrg/update',
    method: 'post',
    data: data
  })
}

// 批量删除监管机构
export function delRegulatorOrg(orgIds) {
  return request({
    url: '/prefund/regulatorOrg/delete',
    method: 'post',
    data: Array.isArray(orgIds) ? orgIds : [orgIds]
  })
}

