import request from '@/api/index'

// 新监管账户页面统一走 /prefund/regulatoryAccountNew，与老 /prefund/regulatoryAccount 完全隔离

// 分页查询
export function pageRegulatoryAccountNew(query) {
  return request({
    url: '/prefund/regulatoryAccountNew/page',
    method: 'post',
    data: query
  })
}

// 详情
export function getRegulatoryAccountNew(accountId) {
  return request({
    url: '/prefund/regulatoryAccountNew/detail',
    method: 'post',
    data: { accountId: accountId }
  })
}

// 新增开户申请（orgId 必填，后端自动带出 mainAccountId）
export function addRegulatoryAccountNew(data) {
  return request({
    url: '/prefund/regulatoryAccountNew/add',
    method: 'post',
    data: data
  })
}

// 修改开户申请
export function updateRegulatoryAccountNew(data) {
  return request({
    url: '/prefund/regulatoryAccountNew/update',
    method: 'post',
    data: data
  })
}

// 批量删除
export function delRegulatoryAccountNew(accountIds) {
  return request({
    url: '/prefund/regulatoryAccountNew/delete',
    method: 'post',
    data: Array.isArray(accountIds) ? accountIds : [accountIds]
  })
}

// 余额查询（备案确认后可用）
export function queryRegulatoryAccountNewBalance(accountId) {
  return request({
    url: '/prefund/regulatoryAccountNew/queryBalanceAmount',
    method: 'post',
    data: { accountId: accountId }
  })
}

// 提交审批
export function submitRegulatoryAccountNew(data) {
  return request({
    url: '/prefund/regulatoryAccountNew/submit',
    method: 'post',
    data: data
  })
}

// 开户审核
export function approvalRegulatoryAccountNew(data) {
  return request({
    url: '/prefund/regulatoryAccountNew/approval',
    method: 'post',
    data: data
  })
}

// 备案确认：confirmResult '1' 无误 / '0' 有误
export function openAccountRecordNew(data) {
  return request({
    url: '/prefund/regulatoryAccountNew/openAccountRecord',
    method: 'post',
    data: data
  })
}

